<template>
  <div class="col-sm-12">
    <add-edit-outgoing-letter-modal
      v-if="isModalVisible"
      :outgoing-letter-to-edit="outgoingLetterBeingEdited"
      @close="closeModal"
      @save-successful="handleSaveSuccessful"
    />

    <detail-outgoing-letter-modal
      v-if="isDetailModalVisible"
      :outgoing-letter-to-view="outgoingLetterBeingViewed"
      @close="closeDetailModal"
    />

    <div class="card">
      <div class="card-header">
        <h3>Daftar Surat Keluar</h3>
      </div>

      <div class="card-body">
        <div class="d-flex justify-content-end align-items-start mb-3">
          <div class="d-flex gap-2">
            <button class="btn btn-outline-light txt-dark" @click="toggleFilterVisibility">
              <i v-if="isFilterVisible" class="fa fa-angle-up me-2"></i>
              <i v-else class="fa fa-angle-down me-2"></i>
              <span> {{ isFilterVisible ? 'Sembunyikan' : 'Tampilkan' }} Filter</span>
            </button>
            <button class="btn btn-success" @click="openAddModal">
              <i class="fa fa-plus me-2"></i>
              <span> Tambah Data</span>
            </button>
          </div>
        </div>

        <div v-if="isFilterVisible" class="border p-3 mb-3 rounded filter-section">
          <div class="row g-3">
            <div class="col-md-3">
              <label class="form-label">Nomor Surat</label>
              <input type="text" class="form-control" v-model="filters.nomor_surat" placeholder="Filter nomor surat...">
            </div>
            <div class="col-md-3">
              <label class="form-label">Perihal</label>
              <input type="text" class="form-control" v-model="filters.perihal" placeholder="Filter perihal...">
            </div>
            <div class="col-md-3">
              <label class="form-label">Instansi Penerima</label>
              <input type="text" class="form-control" v-model="filters.instansi_penerima" placeholder="Filter penerima...">
            </div>
            <div class="col-md-3">
              <label class="form-label">Nama Desa</label>
                <select class="form-select" v-model="filters.id_desa">
                  <option value="">Semua Desa</option>
                  <option v-for="desa in desaList" :key="desa.iddesa" :value="desa.iddesa">
                    {{ desa.wilayah.namawilayah }}
                  </option>
                </select>
            </div>
          </div>
          <div class="d-flex justify-content-end gap-2 mt-3">
            <button class="btn btn-secondary" @click="resetFilters">
              <i class="fa fa-refresh me-2"></i><span>Reset</span>
            </button>
            <button class="btn btn-primary" @click="applyFilters">
                <i class="fa fa-search me-2"></i><span>Cari</span>
            </button>
          </div>
        </div>
      </div>

      <div class="table-responsive signal-table">
        <table class="table table-hover">
          <thead>
            <tr>
              <th scope="col">No</th>
              <th scope="col" @click="sortBy('nomor_surat')">
                Nomor Surat <i class="fa" :class="getSortIcon('nomor_surat')"></i>
              </th>
              <th scope="col" @click="sortBy('perihal')">
                Perihal <i class="fa" :class="getSortIcon('perihal')"></i>
              </th>
              <th scope="col" @click="sortBy('instansi_penerima')">
                Instansi Penerima <i class="fa" :class="getSortIcon('instansi_penerima')"></i>
              </th>
              <th scope="col" @click="sortBy('tanggal_surat')">
                Tanggal Surat <i class="fa" :class="getSortIcon('tanggal_surat')"></i>
              </th>
              <th scope="col" @click="sortBy('nama_wilayah')">
                Desa <i class="fa" :class="getSortIcon('nama_wilayah')"></i>
              </th>
              <th scope="col">Aksi</th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="(item, index) in outgoingLetters" :key="item.id_surat_keluar">
              <th scope="row">{{ (currentPage - 1) * perPage + index + 1 }}</th>
              <td>{{ item.nomor_surat || '-' }}</td>
              <td>{{ item.perihal || '-' }}</td>
              <td>{{ item.instansi_penerima || '-' }}</td>
              <td>{{ formatTanggal(item.tanggal_surat) }}</td>
              <td>{{ item.wilayah?.nama_wilayah || '-' }}</td>
              <td>
                <div class="btn-group">
                  <button class="btn btn-success btn-sm" @click="openSuratFile(item.file_surat)" title="Lihat File Surat">
                      <i class="fa fa-file"></i>
                  </button>
                  <button class="btn btn-info btn-sm" @click="openDetailModal(item)" title="Lihat Detail">
                    <i class="fa fa-eye"></i>
                  </button>
                  <button class="btn btn-primary btn-sm" @click="openEditModal(item)" title="Ubah Data">
                    <i class="fa fa-pencil"></i>
                  </button>
                  <button class="btn btn-danger btn-sm" @click="advancedDeleteAlert(item)" title="Hapus Data">
                    <i class="fa fa-trash"></i>
                  </button>
                </div>
              </td>
            </tr>
            <tr v-if="outgoingLetters.length === 0">
              <td colspan="7" class="text-center">Tidak ada data yang cocok atau tersedia.</td>
            </tr>
          </tbody>
        </table>

        <div class="d-flex flex-column flex-md-row justify-content-md-between align-items-center mt-3 px-3 pb-3">
          <div class="mt-2">
            <span v-if="totalItems > 0" class="text-muted">
              Menampilkan <strong>{{ (currentPage - 1) * perPage + 1 }}</strong> - <strong>{{ Math.min(currentPage * perPage, totalItems) }}</strong> dari <strong>{{ totalItems }}</strong> data
            </span>
          </div>
          <nav v-if="perPage !== -1 && totalPages > 1" class="d-flex align-items-center flex-wrap gap-2 mt-2">
            <ul class="pagination mb-0">
              <li class="page-item" :class="{ disabled: currentPage === 1 }"><button class="page-link" @click="changePage(currentPage - 1)">Prev</button></li>
              <li class="page-item" v-for="page in pageNumbers" :key="page" :class="{ active: currentPage === page }"><button class="page-link" @click="changePage(page)">{{ page }}</button></li>
              <li class="page-item" :class="{ disabled: currentPage === totalPages }"><button class="page-link" @click="changePage(currentPage + 1)">Next</button></li>
            </ul>
          </nav>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { deleteOutgoingLetter, getOutgoingLetters } from '@/services/general/documents/outgoingLetters';
import { getProfiles } from '@/services/general/villageInformation/profile';
import AddEditOutgoingLetterModal from './addEditOutgoingLetterModal.vue';
import DetailOutgoingLetterModal from './detailOutgoingLetter.vue';
import { useToast } from "vue-toastification";

export default {
  components: { AddEditOutgoingLetterModal, DetailOutgoingLetterModal },
  data() {
    return {
      outgoingLetters: [],
      desaList: [],
      sortColumn: 'created_at',
      sortDirection: 'asc',
      isModalVisible: false,
      currentPage: 1,
      perPage: 20,
      totalItems: 0,
      outgoingLetterBeingEdited: null,
      outgoingLetterBeingViewed: null,
      isDetailModalVisible: false,
      isFilterVisible: false,
      filters: {
        nomor_surat: '',
        perihal: '',
        instansi_penerima: '',
        id_desa: '',
      },
      toast: null,
    };
  },
  computed: {
    totalPages() {
      if (this.perPage <= 0) return 1;
      return Math.ceil(this.totalItems / this.perPage);
    },
    pageNumbers() {
      const pages = [];
      const maxVisible = 5;
      let start = Math.max(1, this.currentPage - Math.floor(maxVisible / 2));
      let end = start + maxVisible - 1;
      if (end > this.totalPages) {
        end = this.totalPages;
        start = Math.max(1, end - maxVisible + 1);
      }
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    },
  },
  watch: {
    currentPage() { this.fetchOutgoingLetters(); },
    perPage() { this.currentPage = 1; this.fetchOutgoingLetters(); },
  },
  async mounted() {
    this.toast = useToast();
    await this.fetchDesaList();
    await this.fetchOutgoingLetters();
  },
  methods: {
    async fetchDesaList() {
      try {
        const response = await getProfiles({ limit: -1 });
        this.desaList = response.data?.data || response.data?.[0]?.data || [];
      } catch (error) {
        this.toast.error("Gagal memuat daftar desa");
      }
    },
    openAddModal() {
      this.outgoingLetterBeingEdited = null;
      this.isModalVisible = true;
    },
    openEditModal(item) {
      this.outgoingLetterBeingEdited = { ...item };
      this.isModalVisible = true;
    },
    closeModal() {
      this.isModalVisible = false;
      this.outgoingLetterBeingEdited = null;
    },
    openDetailModal(item) {
      this.outgoingLetterBeingViewed = { ...item };
      this.isDetailModalVisible = true;
    },
    closeDetailModal() {
      this.isDetailModalVisible = false;
      this.outgoingLetterBeingViewed = null;
    },
    openSuratFile(fileUrl) {
      if (fileUrl) {
        window.open(fileUrl, '_blank');
      } else {
        this.toast.info("Tidak ada file surat yang tersedia.", { icon: 'fa fa-info-circle' });
      }
    },
    handleSaveSuccessful() {
      this.closeModal();
      this.fetchOutgoingLetters();
    },
    async fetchOutgoingLetters() {
      try {
        const params = {
          page: this.currentPage,
          limit: this.perPage,
          order: this.sortColumn ? `${this.sortColumn} ${this.sortDirection}` : '',
        };
        const filterParts = Object.entries(this.filters)
          .filter(([, value]) => value !== '')
          .map(([key, value]) => `${key}=${value}`);
        if (filterParts.length > 0) {
          params.filter = filterParts.join(',');
        }
        
        const response = await getOutgoingLetters(params);
        const letterData = response.data?.data || response.data?.[0]?.data || [];
        const meta = response.data?.[0]?.meta?.pagination || {};
        this.outgoingLetters = letterData;
        this.totalItems = meta.total || letterData.length;
      } catch (error) {
        this.toast.error('Gagal memuat data surat keluar.');
      }
    },
    advancedDeleteAlert(item) {
      this.$swal({
        title: `Hapus Surat No. ${item.nomor_surat}?`,
        text: 'Apakah Anda yakin ingin menghapus data ini?',
        icon: 'warning', 
        showCancelButton: true,
        confirmButtonText: '<i class="fa fa-check me-2"></i> Hapus!',
        confirmButtonColor: '#d33',
        cancelButtonText: '<i class="fa fa-times me-2"></i> Batal',
        cancelButtonColor: '#efefef',
        reverseButtons: true
      }).then(async (result) => {
        if (result.isConfirmed) {
          try {
            await deleteOutgoingLetter(item.id_surat_keluar);
            this.toast.success("Data surat keluar berhasil dihapus");
            this.fetchOutgoingLetters();
          } catch (error) {
            this.toast.error("Gagal menghapus data surat keluar");
          }
        }
      });
    },
    sortBy(column) {
      if (this.sortColumn === column) {
        this.sortDirection = this.sortDirection === 'asc' ? 'desc' : 'asc';
      } else {
        this.sortColumn = column;
        this.sortDirection = 'asc';
      }
      this.fetchOutgoingLetters();
    },
    getSortIcon(column) {
      if (this.sortColumn !== column) return 'fa-sort';
      if (this.sortDirection === 'asc') return 'fa-sort-asc';
      return 'fa-sort-desc';
    },
    changePage(page) {
      if (page >= 1 && page <= this.totalPages) {
        this.currentPage = page;
      }
    },
    toggleFilterVisibility() {
      this.isFilterVisible = !this.isFilterVisible;
    },
    applyFilters() {
      this.currentPage = 1;
      this.fetchOutgoingLetters();
    },
    resetFilters() {
      this.filters = {
        nomor_surat: '',
        perihal: '',
        instansi_penerima: '',
        id_desa: '',
      };
      this.sortColumn = 'created_at';
      this.sortDirection = 'asc';
      this.fetchOutgoingLetters();
    },
    formatTanggal(tanggal) {
      if (!tanggal) return '-';
      const options = { day: 'numeric', month: 'long', year: 'numeric' };
      return new Date(tanggal).toLocaleDateString('id-ID', options);
    },
  },
};
</script>

